  match parse_int(input_str) {
    Ok(parsed_val) => {
      match divide_safe(parsed_val, divisor) {
        Ok(final_val) => print("Result: " ++ show(final_val)),
        Err(msg) => print("Error: " ++ msg)
      }
    },
    Err(msg) => print("Error: " ++ msg)
  }
}

