import std/io (println)
import std/fs (readDir, statFile)

-- A recursive function to sum the bytes of all files in a given directory and its subdirectories.
-- It takes the current path as input and returns the total sum of bytes found.
export func sumFileBytesRecursive(path: string) -> int ! {FS} {
  match readDir(path) {
    Ok(entries) => {
      -- Helper function to fold over the list of directory entries,
      -- accumulating the total file size. This function uses letrec for recursion.
      letrec foldEntries = \remainingEntries, currentTotalSum.
        match remainingEntries {
          [] => currentTotalSum, -- Base case: no more entries, return the accumulated sum
          Cons(entry, tail) => {
            let fullPath = path ++ "/" ++ entry.name;

            if entry.isDir -- Check if the current entry is a directory (from DirEntry record)
            then {
              -- If it's a directory, recursively sum its contents and add to the current total.
              let subDirSum = sumFileBytesRecursive(fullPath);
              foldEntries(tail, currentTotalSum + subDirSum)
            }
            else {
              -- If it's a file, retrieve its size and add it to the current total.
              match statFile(fullPath) {
                Ok(fileStat) => foldEntries(tail, currentTotalSum + fileStat.size),
                Err(_) => foldEntries(tail, currentTotalSum) -- Ignore errors for individual files (e.g., permissions)
              }
            }
          }
        }
      in
      foldEntries(entries, 0) -- Start the accumulation for this directory's entries with an initial sum of 0
    },
    Err(_) => 0 -- If the directory cannot be read (e.g., due to permissions or non-existence), it contributes 0 to the total sum
  }
}

export func main() -> () ! {IO, FS} {
  -- The starting path for the recursive byte calculation.
  -- For typical benchmarks, "." refers to the current working directory.
  let rootPath = ".";
  let totalBytes = sumFileBytesRecursive(rootPath);
  print("Total bytes in '" ++ rootPath ++ "' and its subdirectories: " ++ show(totalBytes) ++ " bytes");
}

